// TH14 synthetic training aliases used by this card.
// Native type 12 -> TH14_ARROWHEAD, native type 20 -> TH14_OVAL.
// Same-number slots for native type 0-23; see transcribe/th14/bullet-types.md.
const TH14_ARROWHEAD: int = 544;
const TH14_OVAL: int = 672;

// TH14 v1.00b Stage 2 midboss spell: 飛符「フライングヘッド」
// Source entry: st02mbs.ecl.txt MBossCard1 (139-191); closure MCard01Head (349-382),
// MBossCard1At (193-210), MBossCard1_at (212-234), MBossCard1_at2 (236-284),
// MBossCard1_shadow (286-295), EffChargePoint3, Ecl_EtBreak(_ni), BossItemCard.
//
// Card frame 0 = shell segment start (timerReset :142).  The source attack body starts
// after OPENING_BUFFER; source t=0 is the midboss task's first frame.  The 1920-frame
// slot-0 timeout (:158-159) stops and cleans the attack at source t=1920.

const SPELL_ID: int = 10;          // :160 spell(10, 1920, ...)
const TIME_LIMIT: int = 2404;      // 120 opening + 2280 window + 4 startup margin
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 1920;    // :158 setInterrupt(0,0,1920,...) / :159 setTimeout

// moveCircle / moveCircleRel angular rates, converted rad/frame -> BAM per frame.
const OMEGA_ABS_BAM: int = 273;    // 0.02617994 rad/frame
const OMEGA_REL_BAM: int = 102;    // 0.009817477 rad/frame
const ARROW_COLOR: int = 6;        // etSprite(1, 12, 6)
const OVAL_COLOR: int = 1;         // etSprite(0, 20, 1)

// Ovals from emitter 0: bullet EX is WAIT 160 then DELETE (ANIM/BRIGHT birth stage omitted
// by the approved presentation policy).  Target DELETE is set_life(1).
xformdef MB_OVAL_LIFE {
    wait(160);
    set_life(1);
}

// Arrows from emitter 1: VELTIME 40 -> scalar 0 (angle kept), WAIT, VELTIME 60 -> target.
// step_speed is non-blocking, so @40 is the post-delay of the first step itself.
xformdef MB_ARROW_RAMP(rest: int, target: fx) {
    @40 step_speed(0fx, 40 + 65536 * EASE_LINEAR);
    wait(rest);
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// Shell control: segment event only, no body, not part of the source formation.
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY + ENEMY_KILLALL_EXEMPT, 1);
    spell_begin(0, SPELL_ID, card_pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

async sub card_pattern() {
    wait(OPENING_BUFFER);
    // Entry representative (0,128); MBoss public-lifeSet(12000) is the normal route value,
    // not the SPELL_ID practice branch lifeSet(1900).  The shell is invulnerable.
    _ = spawn_enemy(0fx, 128fx, 12000, 0, 0, 0, mboss_body);
}

async sub mboss_body() {
    // Public MBoss entry state: hurtbox(48,48)->r24, hitbox(40,40)->r20.
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);

    // :152 movePosTime(0,0,0,0) only cancels a position tween; a fresh enemy has none.
    // :161 movePosTime(60,4,0,144): (0,128) -> (0,144), quadratic deceleration.
    // :162 moveLimit(0,128,280,64) is inert on this path (x=0, y=144 stays inside).
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);   // :163

    // :166-171 EffChargePoint3 / anmSelect / anm316 / playSound: presentation, omitted.
    wait(90);
    wait(30);

    // :172 enmCreate("MCard01Head", 0,-24, 5000, 10, 0): relative to parent FINAL.
    var head: int = spawn_enemy($self_x, $self_y - 24fx, 5000, 0, 0, 0, mcard01_head);
    set_self_int(0, 2);   // :174 $I0=2 (no consumer inside this closure; source order kept)

    // :176-189 poll $ENM_CNT<=1 every 10 frames; when open, 90+30 frames then a new head.
    // The invulnerable no-DPS shell never kills the head, so this respawn path is retained
    // but unreachable (see report).
    var t: int = 180;
    while t < SOURCE_LIMIT {
        wait(10);
        t = t + 10;
        if t >= SOURCE_LIMIT { break; }
        if enemy_alive(head) == 0 {
            wait(90);
            wait(30);
            t = t + 120;
            if t < SOURCE_LIMIT {
                head = spawn_enemy($self_x, $self_y - 24fx, 5000, 0, 0, 0, mcard01_head);
            }
        }
    }

    // MBossEscape (:326-347) timeout path: etClear(640) + enmKillAll + leave + delete.
    // spellEnd / UI / chapter / lifeSet are shell bookkeeping; the phase timer runs to
    // TIME_LIMIT and the extra window covers this 60-frame exit.
    kill_all_enemies(KILL_SILENT);
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_to(60, -224fx, 64fx, EASE_QUAD_OUT);   // :343 movePosTime(60,4,-224,64)
    wait(60);
    // main task returns -> enemy leaves (D9)
}

async sub mcard01_head() {
    set_invuln(65535);
    set_hurtbox(7fx);   // :354 setHurtbox(14,14) -> r7
    set_hitbox(6fx);    // :355 setHitbox(12,12) -> r6
    // :356 setBoss(2) is boss-slot registration/UI.  :357 flagSet(268)=0x4|0x8|0x100:
    // 0x4/0x8 skip offscreen recovery (target enemies have no offscreen cull), 0x100 unknown.
    //
    // :359 moveCircle(%RANDRAD, 0.02617994, 0, 0.2) on ABS and :360 moveCircleRel(
    // %RANDRAD, 0.009817477, 0, 0.6) on REL: same centre, r=0 growing 0.2 / 0.6 px/frame,
    // phase advancing 273 / 102 BAM/frame.  Final position = ABS + REL.
    var cx: fx = $self_x;
    var cy: fx = $self_y;
    var ta: angle = (rand(65536) - 32768) as angle;   // %RANDRAD (ABS phase)
    var tr: angle = (rand(65536) - 32768) as angle;   // %RANDRAD (REL phase)
    var ra: fx = 0fx;
    var rr: fx = 0fx;
    for i in 0..120 {
        ra = ra + 0.2fx;
        rr = rr + 0.6fx;
        ta = ta + (OMEGA_ABS_BAM as angle);
        tr = tr + (OMEGA_REL_BAM as angle);
        var px1: fx = cx + ra * cos(ta) + rr * cos(tr);
        var py1: fx = cy + ra * sin(ta) + rr * sin(tr);
        move_vel_xy(0, px1 - $self_x, py1 - $self_y, EASE_LINEAR);
        wait(1);
    }
    // :362/363 moveCircle(-999999,-999999,-999999,0): radially frozen, omega/radius kept.
    // :364 diffI($A, 10,20,30,40); :370-371 $A ramps up to 64.
    var n: int = 10 + 10 * global(GVAR_RANK);
    loop {
        // :367 %F0=pi/2, :368 enmCreate("MBossCard1At",0,0,10,10,0)
        _ = spawn_enemy($self_x, $self_y, 10, 0, 0, 0, mboss_at(90deg));
        // :369 @MBossCard1_at2($A) async: emitter-1 burst owned by this head task tree.
        spawn mb_at2(n);
        if n < 64 { n = n + 1; }
        for k in 0..160 {   // :373 wait(160), motion continues
            ta = ta + (OMEGA_ABS_BAM as angle);
            tr = tr + (OMEGA_REL_BAM as angle);
            var px2: fx = cx + ra * cos(ta) + rr * cos(tr);
            var py2: fx = cy + ra * sin(ta) + rr * sin(tr);
            move_vel_xy(0, px2 - $self_x, py2 - $self_y, EASE_LINEAR);
            wait(1);
        }
    }
}

// :212-234 MBossCard1_at: emitter 0 stream on the MBossCard1At drone.
async sub mboss_at_fire() {
    var i: int = 0;
    while i < 700 {
        // :228 etAngle(0, %ABS_ANGLE, 0): one 1-way fixed ring along the ABS motion angle.
        var a: angle = $self_angle;
        // Birth ANIM displacement is -4*velocity = -0.04px along the bullet angle.
        var sx: fx = $self_x - 0.04fx * cos(a);
        var sy: fx = $self_y - 0.04fx * sin(a);
        // :217 type20 OVAL color 1, :220 speed 0.01 (M=1 takes the first endpoint),
        // :223 WAIT160 + :224 DELETE are in MB_OVAL_LIFE.
        _ = fire(TH14_OVAL, OVAL_COLOR, sx, sy, 0.01fx, a, MB_OVAL_LIFE, none);
        wait(2);   // :230
        i = i + 1;
    }
}

// :193-210 MBossCard1At: offscreen-culled emitter drone, no body.
async sub mboss_at(dir: angle) {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);   // :196 flagSet(288)=0x20 no hit/body (+0x100 unknown)
    spawn mboss_at_fire();              // :199 @MBossCard1_at() async

    // :197 moveVel(%F0,1) then :198 moveSpeedTime(60,0,2.4): speed 1 -> 2.4 linearly.
    // :201-207 ten 60-frame blocks; each block end sets a new per-frame angle increment
    // %A = %RANDRAD/300 (mode 7, about +-109 BAM/frame), replacing the previous one.
    var ang: angle = dir;
    var w: angle = 0deg;
    var t: int = 0;
    for seg in 0..10 {
        for k2 in 0..60 {
            var spd: fx = 2.4fx;
            if t < 60 { spd = 1fx + (1.4fx * ((t + 1) as fx)) / 60fx; }
            move_vel_xy(0, spd * cos(ang), spd * sin(ang), EASE_LINEAR);
            wait(1);
            t = t + 1;
            ang = ang + w;
        }
        var rw: int = rand(65536) - 32768;
        w = (rw / 300) as angle;
    }
    // task returns -> enemy leaves
}

// :236-284 MBossCard1_at2: emitter 1, full ring of N arrows, B bursts.
async sub mb_at2(n: int) {
    // :256 stack WAIT: E/N/H 100, L 50; :266 VELTIME target: E/N/H 1.0, L 2.5.
    // :267 diffI($B,3,3,3,5); :271-280 burst gap 30, L 20.
    var rest: int = 100;
    var target: fx = 1fx;
    var b: int = 3;
    var gap: int = 30;
    if global(GVAR_RANK) == RANK_LUNATIC {
        rest = 50;
        target = 2.5fx;
        b = 5;
        gap = 20;
    }
    for burst in 0..b {
        // :240 etAim(1,2) aimed ring; base A is resolved per burst (etOn moment).
        var aim_base: angle = aim_player() + 90deg;
        for i2 in 0..n {
            // :242 etCount(N,1), :243 angle = A + pi/2 + R(i) + q*delta with q=0.
            var aa: angle = aim_base + (((i2 * 65536) / n) as angle);
            // Birth ANIM displacement -4*3 = -12px along each bullet's own angle.
            var ax: fx = $self_x - 12fx * cos(aa);
            var ay: fx = $self_y - 12fx * sin(aa);
            // :241 type12 ARROWHEAD color 6, :244 speed 3 (M=1), :256-266 ramp xform.
            _ = fire(TH14_ARROWHEAD, ARROW_COLOR, ax, ay, 3fx, aa, MB_ARROW_RAMP(rest, target), none);
        }
        wait(gap);
    }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
